    public static void main(String[]args)throws Exception{Result r=run();System.out.println("Composition decision-time provenance: "+r.verdict());}

    static Result run()throws Exception{
        verifySources();Files.createDirectories(OUT);Map<Path,String>before=sourceHashes();
        Map<Integer,SourceGame>sourceGames=readSourceGames();List<SourceApp>sourceApps=readSourceApps();
        Selection selection=selectCases(sourceGames,sourceApps);Map<Integer,CompositionAuditOnlySemanticsRuntime.ScheduleCase>schedule=readSchedule();
        Map<String,CompositionFreshHoldoutCandidateGameplayAudit.Lineup>lineups=CompositionFreshHoldoutCandidateGameplayAudit.readCanonical().stream().collect(Collectors.toMap(CompositionFreshHoldoutCandidateGameplayAudit.Lineup::id,Function.identity()));
        MatchSimulator offSimulator=CompositionAuditOnlySemanticsRuntime.simulator(TeamCompositionGameplayMode.OFF,CompositionSemanticsAuditExecutionAuthorization.none());
        List<ReplayCase>replays=new ArrayList<>();List<CompositionWinnerDecisionProvenance>provenance=new ArrayList<>();int sourceMismatch=0,randomMismatch=0;
        for(int caseIndex:selection.caseIndexes()){
            var row=required(schedule,caseIndex);MatchChampionAssignments assignments=CompositionAuditOnlySemanticsRuntime.assignments(required(lineups,row.blueLineupId()),required(lineups,row.redLineupId()));
            var off=CompositionAuditOnlySemanticsRuntime.simulate(offSimulator,row,assignments);var candidate=CompositionAuditOnlySemanticsRuntime.simulate(CompositionKeySpecificFreshHoldoutGameplayAudit.candidateSimulator(caseIndex),row,assignments);
            var pair=CompositionAuditOnlySemanticsRuntime.pair(row,off,candidate);SourceGame source=required(sourceGames,caseIndex);
            boolean sourceExact=source.matches(pair);if(!sourceExact)sourceMismatch++;
            if(pair.preDivergenceRandomMismatch()!=0)randomMismatch++;
            PublicDifference difference=publicDifference(off,candidate);StructureDifference structures=structureDifference(off,candidate);ObjectiveDifference objectives=objectiveDifference(off,candidate);
            replays.add(new ReplayCase(row,source,off,candidate,pair,difference,structures,objectives,sourceExact));
            provenance.addAll(candidate.compositionRuntimeDiagnostics().winnerDecisionProvenance());
        }
        List<Integer>validationCases=selection.caseIndexes().stream().sorted(Comparator.comparing(x->sha256("replay|"+x))).limit(REPLAY_VALIDATIONS).toList();int deterministicMismatch=0;
        for(int caseIndex:validationCases){var row=required(schedule,caseIndex);var assignments=CompositionAuditOnlySemanticsRuntime.assignments(required(lineups,row.blueLineupId()),required(lineups,row.redLineupId()));var a=CompositionAuditOnlySemanticsRuntime.simulate(CompositionKeySpecificFreshHoldoutGameplayAudit.candidateSimulator(caseIndex),row,assignments);var b=CompositionAuditOnlySemanticsRuntime.simulate(CompositionKeySpecificFreshHoldoutGameplayAudit.candidateSimulator(caseIndex),row,assignments);if(!CompositionAuditOnlySemanticsRuntime.hash(a.timeline()).equals(CompositionAuditOnlySemanticsRuntime.hash(b.timeline()))||!CompositionAuditOnlySemanticsRuntime.hash(a.randomTrace()).equals(CompositionAuditOnlySemanticsRuntime.hash(b.randomTrace()))||!CompositionAuditOnlySemanticsRuntime.hash(a.compositionRuntimeDiagnostics().winnerDecisionProvenance()).equals(CompositionAuditOnlySemanticsRuntime.hash(b.compositionRuntimeDiagnostics().winnerDecisionProvenance())))deterministicMismatch++;}
        List<CompositionWinnerDecisionProvenance>actual=provenance.stream().filter(CompositionDecisionTimeProvenanceCapture::actualFlip).filter(x->KEYS.contains(x.context())).toList();
        List<CompositionWinnerDecisionProvenance>controls=selection.controls().stream().map(id->provenance.stream().filter(x->id.matches(x)).findFirst().orElseThrow(()->new IllegalStateException("Missing control "+id))).toList();
        Map<String,List<RuleContribution>>rules=ruleContributions(replays,lineups);
        Correction correction=correct4c6();List<CorrectedSafety>safety=correct4c7(sourceApps);
        int captureMissing=(int)KEYS.stream().mapToLong(c->expected(c)-actual.stream().filter(x->x.context()==c).count()).map(Math::abs).sum();
        int mutation=0;int errors=sourceMismatch+randomMismatch+deterministicMismatch+captureMissing+mutation;
        String verdict=errors>0?"BLOCKED_BY_COMPOSITION_PROVENANCE_CAPTURE_INTEGRITY":!correction.selectionUnchanged()?"REVIEW_CORRECTED_CALIBRATION_CHANGES_CANDIDATE_SELECTION":"READY_FOR_PHASE_13D4C7_2_GAMEPLAY_PLAUSIBILITY_AND_SAFETY_POLICY_DECISION";
        Result result=new Result(selection,replays,List.copyOf(provenance),actual,controls,rules,correction,safety,sourceMismatch,randomMismatch,deterministicMismatch,mutation,errors,verdict,before,sourceHashes());write(result);verifySources();if(!before.equals(sourceHashes()))throw new IllegalStateException("source artifact drift");return result;
    }

    static void verifySources()throws IOException{check(H7.resolve("composition-key-specific-fresh-holdout-summary.csv"),H7_SUM);check(H7.resolve("composition-key-specific-fresh-holdout-audit.log"),H7_AUD);check(A71.resolve("composition-fresh-holdout-attribution-summary.csv"),A71_SUM);check(A71.resolve("composition-fresh-holdout-attribution-audit.log"),A71_AUD);FrozenCompositionKeySpecificChannelCandidate.verifyIdentity(FrozenCompositionKeySpecificChannelCandidate.VERSION,FrozenCompositionKeySpecificChannelCandidate.HASH);}
    static void check(Path p,String hash)throws IOException{if(!hash.equals(sha256(p)))throw new IllegalStateException("source hash mismatch "+p);}

    static Map<Integer,SourceGame>readSourceGames()throws IOException{return readSourceGames(H7);}
    static Map<Integer,SourceGame>readSourceGames(Path sourceRoot)throws IOException{Map<Integer,SourceGame>out=new HashMap<>();for(var r:read(sourceRoot.resolve("composition-fresh-holdout-paired-games.csv"))){SourceGame x=new SourceGame(i(r,"caseIndex"),l(r,"seed"),r.get("blueLineupId"),r.get("redLineupId"),TeamSide.valueOf(r.get("offWinner")),TeamSide.valueOf(r.get("candidateWinner")),i(r,"offDuration"),i(r,"candidateDuration"),b(r,"publicDivergence"),b(r,"objectiveChanged"),b(r,"structureChanged"));out.put(x.caseIndex(),x);}return Map.copyOf(out);}
    static List<SourceApp>readSourceApps()throws IOException{List<SourceApp>out=new ArrayList<>();for(var r:read(H7.resolve("composition-fresh-holdout-winner-applications.csv"))){TeamCompositionContext c=TeamCompositionContext.valueOf(r.get("context"));int ci=i(r,"caseIndex"),attempt=i(r,"attemptId");double bg=d(r,"baselineGap"),edge=d(r,"compositionEdge"),gain=d(r,"candidateGain"),mod=d(r,"candidateModifier"),cg=d(r,"candidateGap"),p=d(r,"candidateProbability"),sample=d(r,"winnerRandom");TeamSide winner=TeamSide.valueOf(r.get("winner"));TeamSide off;if(c==TeamCompositionContext.SKIRMISH){double bp=weightedBaseline(bg,mod,cg,p);off=sample<bp?TeamSide.BLUE:TeamSide.RED;}else off=bg+(sample-.5)*56>=0?TeamSide.BLUE:TeamSide.RED;out.add(new SourceApp(new ApplicationId(ci,attempt,c),i(r,"timeSeconds"),bg,edge,gain,mod,cg,p,sample,winner,off!=winner));}return List.copyOf(out);}
    static double weightedBaseline(double bg,double mod,double cg,double p){if(Math.abs(mod)<1e-12)return p;double den=2*p-1;if(Math.abs(den)<1e-12)return .5;return clamp(.5+bg/(2*(cg/den)));}
    static Selection selectCases(Map<Integer,SourceGame>games,List<SourceApp>apps){Set<Integer>cases=games.values().stream().filter(SourceGame::publicDivergence).map(SourceGame::caseIndex).collect(Collectors.toCollection(TreeSet::new));apps.stream().filter(SourceApp::actualFlip).filter(x->KEYS.contains(x.id().context())).forEach(x->cases.add(x.id().caseIndex()));List<ApplicationId>controls=new ArrayList<>();for(var c:KEYS){long n=expected(c)*2L;List<ApplicationId>picked=apps.stream().filter(x->x.id().context()==c&&!x.actualFlip()).map(SourceApp::id).sorted(Comparator.comparing(x->sha256(x.stableId()))).limit(n).toList();controls.addAll(picked);picked.forEach(x->cases.add(x.caseIndex()));}if(cases.size()>600)throw new IllegalStateException("Replay case union exceeds budget="+cases.size());return new Selection(List.copyOf(cases),List.copyOf(controls));}
    static Map<Integer,CompositionAuditOnlySemanticsRuntime.ScheduleCase>readSchedule()throws IOException{return readSchedule(H7);}
    static Map<Integer,CompositionAuditOnlySemanticsRuntime.ScheduleCase>readSchedule(Path sourceRoot)throws IOException{Map<Integer,CompositionAuditOnlySemanticsRuntime.ScheduleCase>out=new HashMap<>();int audit=0;for(var r:read(sourceRoot.resolve("composition-fresh-holdout-schedule.csv"))){int ci=i(r,"caseIndex");out.put(ci,new CompositionAuditOnlySemanticsRuntime.ScheduleCase(audit++,ci,i(r,"orientationGroupId"),l(r,"seed"),i(r,"orientation"),r.get("blueLineupId"),r.get("redLineupId"),r.get("pairHash")));}return Map.copyOf(out);}

    static PublicDifference publicDifference(MatchSimulator.SimulationResult a,MatchSimulator.SimulationResult b){List<MatchEvent>ae=a.timeline().getEvents(),be=b.timeline().getEvents();int time=Integer.MAX_VALUE;String event="NONE";for(int i=0;i<Math.min(ae.size(),be.size());i++)if(!CompositionAuditOnlySemanticsRuntime.hash(ae.get(i)).equals(CompositionAuditOnlySemanticsRuntime.hash(be.get(i)))){time=Math.min(ae.get(i).getTimeSeconds(),be.get(i).getTimeSeconds());event=eventIdentity(ae.get(i))+" <> "+eventIdentity(be.get(i));break;}List<MatchSnapshot>as=a.timeline().getSnapshots(),bs=b.timeline().getSnapshots();String field="NONE";for(int i=0;i<Math.min(as.size(),bs.size());i++)if(!CompositionAuditOnlySemanticsRuntime.hash(as.get(i)).equals(CompositionAuditOnlySemanticsRuntime.hash(bs.get(i)))){int st=Math.min(as.get(i).getTimeSeconds(),bs.get(i).getTimeSeconds());if(st<=time){time=st;field=firstMapDifference(as.get(i),bs.get(i));}break;}return new PublicDifference(time==Integer.MAX_VALUE?-1:time,event,field);}
    static String eventIdentity(MatchEvent e){return e.getTimeSeconds()+"|"+e.getType()+"|"+e.getCombatSource()+"|"+e.getStructureKind()+"|"+e.getStructureTowerTier()+"|"+e.getStructureLane()+"|"+e.getStructureAttackingSide()+"|"+e.getStructureDefendingSide()+"|"+e.getStructureActionSource();}
    static String firstMapDifference(Object a,Object b){Map<String,Object>x=CompositionAuditOnlySemanticsRuntime.JSON.convertValue(a,new TypeReference<>(){}),y=CompositionAuditOnlySemanticsRuntime.JSON.convertValue(b,new TypeReference<>(){});return x.keySet().stream().filter(k->!Objects.equals(x.get(k),y.get(k))).findFirst().orElse("SERIALIZED_NESTED_FIELD");}
    static ObjectiveDifference objectiveDifference(MatchSimulator.SimulationResult a,MatchSimulator.SimulationResult b){Set<String>x=objectiveEvents(a),y=objectiveEvents(b);Set<String>diff=new LinkedHashSet<>(x);diff.removeAll(y);Set<String>reverse=new LinkedHashSet<>(y);reverse.removeAll(x);diff.addAll(reverse);String kinds=diff.stream().map(s->s.split("\\|")[1]).distinct().sorted().collect(Collectors.joining("|"));boolean soul=a.soulOwner()!=b.soulOwner()||a.soulClaimedAtSeconds()!=b.soulClaimedAtSeconds();return new ObjectiveDifference(!x.equals(y)||soul,kinds.isEmpty()?"NONE":kinds,soul);}
    static Set<String>objectiveEvents(MatchSimulator.SimulationResult r){return r.timeline().getEvents().stream().filter(e->e.getType()==MatchEventType.DRAGON||e.getType()==MatchEventType.BARON||e.getType()==MatchEventType.ELDER).map(e->e.getTimeSeconds()+"|"+e.getType()+"|"+e.getObjectiveDecision()).collect(Collectors.toCollection(LinkedHashSet::new));}
    static StructureDifference structureDifference(MatchSimulator.SimulationResult a,MatchSimulator.SimulationResult b){String x=structureEvents(a),y=structureEvents(b);MatchSnapshot as=a.timeline().getSnapshots().getLast(),bs=b.timeline().getSnapshots().getLast();boolean nexusTurret=as.getBlueNexusTurretsRemaining()!=bs.getBlueNexusTurretsRemaining()||as.getRedNexusTurretsRemaining()!=bs.getRedNexusTurretsRemaining();boolean nexus=as.isBlueNexusAlive()!=bs.isBlueNexusAlive()||as.isRedNexusAlive()!=bs.isRedNexusAlive()||a.winnerSide()!=b.winnerSide();return new StructureDifference(!x.equals(y),nexusTurret,nexus,x,y);}
    static String structureEvents(MatchSimulator.SimulationResult r){return r.timeline().getEvents().stream().filter(e->e.getType()==MatchEventType.TOWER).map(CompositionDecisionTimeProvenanceCapture::eventIdentity).collect(Collectors.joining(">"));}

    static Map<String,List<RuleContribution>>ruleContributions(List<ReplayCase>replays,Map<String,CompositionFreshHoldoutCandidateGameplayAudit.Lineup>lineups){Map<String,List<RuleContribution>>out=new HashMap<>();TeamCompositionAnalyzer analyzer=new TeamCompositionAnalyzer();for(ReplayCase replay:replays){var blue=input(required(lineups,replay.row().blueLineupId()),analyzer);var red=input(required(lineups,replay.row().redLineupId()),analyzer);var analysis=new CompositionInteractionEvaluator().evaluate(blue,red,FrozenCompositionInteractionRuntimePolicy.current().formula());for(var c:KEYS){var interaction=analysis.contexts().get(c);Map<String,CompositionInteractionRuleEvaluation>left=interaction.teamAToTeamB().rules().stream().collect(Collectors.toMap(CompositionInteractionRuleEvaluation::ruleId,Function.identity()));Map<String,CompositionInteractionRuleEvaluation>right=interaction.teamBToTeamA().rules().stream().collect(Collectors.toMap(CompositionInteractionRuleEvaluation::ruleId,Function.identity()));List<RuleContribution>values=new ArrayList<>();for(var rule:CompositionInteractionRuleCatalog.rules(c)){var l=left.get(rule.ruleId());var r=right.get(rule.ruleId());values.add(new RuleContribution(rule.ruleId(),c,l.weightedPressure()/3.0,-r.weightedPressure()/3.0,(l.weightedPressure()-r.weightedPressure())/3.0,l.sourceSignal().stableId()+"->"+l.oppositionSignals().stream().map(CompositionSignalRef::stableId).collect(Collectors.joining("+")),l.exposure(),r.exposure()));}out.put(replay.row().caseIndex()+"|"+c,List.copyOf(values));}}return Map.copyOf(out);}
    static CompositionInteractionInput input(CompositionFreshHoldoutCandidateGameplayAudit.Lineup lineup,TeamCompositionAnalyzer analyzer){EnumMap<Position,ChampionRoleKey>roles=new EnumMap<>(Position.class);lineup.champions().forEach((p,c)->roles.put(p,new ChampionRoleKey(c,p)));return CompositionInteractionInput.fromAnalysis(analyzer.analyze(new TeamCompositionLineup(roles),ThirtyChampionCompositionProfiles.all()));}

    static Correction correct4c6()throws IOException{Map<Integer,String>split=new HashMap<>();for(var r:read(C46.resolve("composition-channel-calibration-dataset-split.csv")))split.put(i(r,"caseIndex"),r.get("split"));Map<TeamCompositionContext,Bands>bands=new EnumMap<>(TeamCompositionContext.class);for(var r:read(C46.resolve("composition-winner-decision-band-thresholds.csv"))){TeamCompositionContext c=TeamCompositionContext.valueOf(r.get("context"));if(KEYS.contains(c))bands.put(c,new Bands(d(r,"p25"),d(r,"p75")));}Map<TeamCompositionContext,List<Grid>>grid=new EnumMap<>(TeamCompositionContext.class);KEYS.forEach(c->grid.put(c,new ArrayList<>()));for(var r:read(C46.resolve("composition-winner-target-ratio-grid.csv"))){TeamCompositionContext c=TeamCompositionContext.valueOf(r.get("context"));if(KEYS.contains(c))grid.get(c).add(new Grid(d(r,"targetRatio"),d(r,"candidateGain")));}Map<TeamCompositionContext,List<C46Row>>rows=new EnumMap<>(TeamCompositionContext.class);KEYS.forEach(c->rows.put(c,new ArrayList<>()));for(var r:read(RUNTIME46.resolve("composition-winner-channel-observations.csv"))){TeamCompositionContext c=TeamCompositionContext.valueOf(r.get("applicationKey").split("\\|")[0]);if(KEYS.contains(c)){int ci=i(r,"caseIndex");rows.get(c).add(new C46Row(split.get(ci),d(r,"baselineGap"),d(r,"rawWinnerEdge"),d(r,"winnerRandomSample")));}}List<CorrectionMetric>metrics=new ArrayList<>();Map<TeamCompositionContext,Grid>selected=new EnumMap<>(TeamCompositionContext.class);for(var c:KEYS){for(Grid g:grid.get(c)){metrics.add(correctMetric(c,"CALIBRATION",g,rows.get(c),bands.get(c)));}Grid choice=grid.get(c).stream().filter(g->g.ratio()>0).filter(g->metrics.stream().anyMatch(m->m.context()==c&&m.partition().equals("CALIBRATION")&&m.ratio()==g.ratio()&&m.safe())).min(Comparator.comparingDouble((Grid g)->Math.abs(g.ratio()-.05)).thenComparingDouble(g->Math.abs(g.gain()))).orElseThrow();selected.put(c,choice);metrics.add(correctMetric(c,"VALIDATION",choice,rows.get(c),bands.get(c)));}boolean unchanged=selected.values().stream().allMatch(x->Math.abs(x.ratio()-.05)<1e-12);return new Correction(List.copyOf(metrics),Map.copyOf(selected),unchanged);}
    static CorrectionMetric correctMetric(TeamCompositionContext c,String partition,Grid g,List<C46Row>all,Bands bands){List<C46Row>rows=all.stream().filter(x->x.partition().equals(partition)).toList();long near=0,mid=0,far=0,flips=0,nonNearApps=0;for(C46Row r:rows){double threshold=.5-r.baselineGap()/56.0,margin=Math.abs(r.sample()-threshold);String band=bands.band(margin);if(!band.equals("NEAR"))nonNearApps++;TeamSide off=r.sample()>=threshold?TeamSide.BLUE:TeamSide.RED;double candidateThreshold=.5-(r.baselineGap()+g.gain()*r.edge())/56.0;TeamSide candidate=r.sample()>=candidateThreshold?TeamSide.BLUE:TeamSide.RED;if(off!=candidate){flips++;if(band.equals("NEAR"))near++;else if(band.equals("MID"))mid++;else far++;}}double nonNearRate=rate(mid+far,nonNearApps),concentration=flips==0?1:rate(near,flips);boolean safe=far==0&&nonNearRate<=.01&&concentration>=.95;return new CorrectionMetric(c,partition,g.ratio(),g.gain(),rows.size(),flips,near,mid,far,nonNearRate,concentration,safe);}
    static List<CorrectedSafety>correct4c7(List<SourceApp>apps){List<CorrectedSafety>out=new ArrayList<>();for(var c:KEYS){long n=0,near=0,mid=0,far=0,nonNearApps=0;Bands bands=BANDS.get(c);for(SourceApp a:apps.stream().filter(x->x.id().context()==c).toList()){double threshold=.5-a.baselineGap()/56,margin=Math.abs(a.sample()-threshold);String band=bands.band(margin);if(!band.equals("NEAR"))nonNearApps++;if(a.actualFlip()){n++;if(band.equals("NEAR"))near++;else if(band.equals("MID"))mid++;else far++;}}long source=switch(c){case TEAMFIGHT->428;case SIEGE->94;case BASE_DEFENSE->137;default->0;};long fp=switch(c){case TEAMFIGHT->389;case SIEGE->84;case BASE_DEFENSE->124;default->0;};long fn=switch(c){case TEAMFIGHT->50;case SIEGE->8;case BASE_DEFENSE->8;default->0;};boolean safe=far==0&&rate(mid+far,nonNearApps)<=.01&&rate(near,n)>=.95;out.add(new CorrectedSafety(c,source,n,fp,fn,near,mid,far,safe));}return List.copyOf(out);}

    static void write(Result r)throws IOException{manifest();candidate();replayFiles(r);semantics();provenanceFiles(r);factorFiles(r);ruleFiles(r);analysisFiles(r);correctionFiles(r);propagationFiles(r);scopePolicyIntegritySummary(r);}
