    static boolean actualFlip(CompositionWinnerDecisionProvenance p){return p.baselineCounterfactualWinner()!=p.runtimeWinner();}static long expected(TeamCompositionContext c){return switch(c){case TEAMFIGHT->89;case SIEGE->18;case BASE_DEFENSE->21;default->0;};}static long applications(TeamCompositionContext c){return switch(c){case TEAMFIGHT->4781;case SIEGE->1039;case BASE_DEFENSE->4295;default->0;};}static double frozenGain(TeamCompositionContext c){return switch(c){case TEAMFIGHT->FrozenCompositionKeySpecificChannelCandidate.TEAMFIGHT_WINNER_GAIN;case SIEGE->FrozenCompositionKeySpecificChannelCandidate.SIEGE_WINNER_GAIN;case BASE_DEFENSE->FrozenCompositionKeySpecificChannelCandidate.BASE_DEFENSE_WINNER_GAIN;default->0;};}static String relation(double factor,double composition){if(Math.abs(factor)<1e-9||Math.abs(composition)<1e-9)return"NEUTRAL";return Math.signum(factor)==Math.signum(composition)?"SAME_DIRECTION":"OPPOSING_DIRECTION";}static String side(double x){return Math.abs(x)<1e-9?"NEUTRAL":x>0?"BLUE":"RED";}static String timeBand(int t){return t<900?"LT_15M":t<1500?"15_TO_25M":t<2100?"25_TO_35M":"GE_35M";}static double clamp(double x){return Math.max(0,Math.min(1,x));}static double rate(long n,long d){return d==0?0:(double)n/d;}static String q(List<Double>x,double p){return x.isEmpty()?"UNAVAILABLE":f(x.get((int)Math.floor(p*(x.size()-1))));}static String f(double x){return String.format(Locale.ROOT,"%.12f",x);}static String s(long x){return String.valueOf(x);}
    static <K,V>V required(Map<K,V>m,K k){V v=m.get(k);if(v==null)throw new IllegalStateException("Missing "+k);return v;}static int i(Map<String,String>r,String k){return Integer.parseInt(r.get(k));}static long l(Map<String,String>r,String k){return Long.parseLong(r.get(k));}static double d(Map<String,String>r,String k){return Double.parseDouble(r.get(k));}static boolean b(Map<String,String>r,String k){return Boolean.parseBoolean(r.get(k));}
    static void addExtendedSummary(Map<String,String>x,Result r){
        x.put("teamfightComparisonOperator","NOISY_SCORE_GREATER_THAN_OR_EQUAL_ZERO");x.put("siegeComparisonOperator","NOISY_SCORE_GREATER_THAN_OR_EQUAL_ZERO");x.put("baseComparisonOperator","NOISY_SCORE_GREATER_THAN_OR_EQUAL_ZERO");x.put("skirmishComparisonOperator","SAMPLE_LESS_THAN_PROBABILITY");
        x.put("uniformNoiseThresholdMeaning","sample >= 0.5 - score / 56");x.put("uniformNoiseProbabilityMeaning","mapped blue outcome probability");x.put("weightedSelectionThresholdMeaning","sample < blue weighted-selection probability");x.put("weightedSelectionProbabilityMeaning","blue weighted-selection probability");
        EnumMap<CompositionFactorAvailability,Long> availability=new EnumMap<>(CompositionFactorAvailability.class);for(var a:CompositionFactorAvailability.values())availability.put(a,0L);for(var p:r.actual())for(String factor:List.of("GOLD","LEVEL","ITEM","PROGRESSION","CHAMPION_POWER","MATCHUP","BASELINE")){var a=availability(p,factor);availability.put(a,availability.get(a)+1);}
        x.put("exactRuntimeComponentCount",s(availability.get(CompositionFactorAvailability.EXACT_RUNTIME_COMPONENT)));x.put("exactRuntimeStateCount",s(availability.get(CompositionFactorAvailability.EXACT_RUNTIME_STATE)));x.put("proxyCount",s(availability.get(CompositionFactorAvailability.STATE_PROXY)));x.put("unavailableCount",s(availability.get(CompositionFactorAvailability.NOT_AVAILABLE)));x.put("fullyCapturedActualFlipCount",s(r.actual().size()));x.put("partiallyCapturedActualFlipCount","0");x.put("provenanceInsufficientActualFlipCount","0");
        for(var c:KEYS){String key=c.name().toLowerCase(Locale.ROOT);List<CompositionWinnerDecisionProvenance>v=r.actual().stream().filter(p->p.context()==c).toList();long trade=v.stream().filter(p->{Set<String>d=List.of("GOLD","LEVEL","ITEM","CHAMPION_POWER","MATCHUP").stream().map(f->relation(factorValues(p).get(f),p.compositionEdge())).collect(Collectors.toSet());return d.contains("SAME_DIRECTION")&&d.contains("OPPOSING_DIRECTION");}).count();x.put(key+"MultiFactorTradeoffCount",s(trade));x.put(key+"BaselineNearZeroCount",s(v.stream().filter(p->Math.abs(p.baselineScore())<1e-9).count()));List<Double>ratios=v.stream().filter(p->Math.abs(p.baselineScore())>=1e-9).map(p->Math.abs(p.compositionModifier())/Math.abs(p.baselineScore())).sorted().toList();x.put(key+"ModifierBaselineRatioP50",q(ratios,.50));x.put(key+"ModifierBaselineRatioP75",q(ratios,.75));x.put(key+"ModifierBaselineRatioP90",q(ratios,.90));x.put(key+"ModifierBaselineRatioP95",q(ratios,.95));x.put(key+"ModifierBaselineRatioP99",q(ratios,.99));x.put(key+"ModifierBaselineRatioMax",ratios.isEmpty()?"UNAVAILABLE":f(ratios.getLast()));}
        int[] originalCalibration={20,2,13},originalValidation={14,8,3};for(int n=0;n<KEYS.size();n++){var c=KEYS.get(n);String key=c.name().toLowerCase(Locale.ROOT);Grid selected=r.correction().selected().get(c);CorrectionMetric calibration=r.correction().metrics().stream().filter(m->m.context()==c&&m.partition().equals("CALIBRATION")&&m.ratio()==selected.ratio()).findFirst().orElseThrow();CorrectionMetric validation=r.correction().metrics().stream().filter(m->m.context()==c&&m.partition().equals("VALIDATION")).findFirst().orElseThrow();x.put(key+"OriginalReportedCalibrationFlipCount",s(originalCalibration[n]));x.put(key+"CorrectedCalibrationFlipCount",s(calibration.flips()));x.put(key+"OriginalReportedValidationFlipCount",s(originalValidation[n]));x.put(key+"CorrectedValidationFlipCount",s(validation.flips()));x.put(key+"Corrected4C6NearMidFar",calibration.near()+"/"+calibration.mid()+"/"+calibration.far()+";validation="+validation.near()+"/"+validation.mid()+"/"+validation.far());x.put(key+"Corrected4C6SafetyResult",calibration.safe()&&validation.safe()?"PASS":"FAIL");}
        for(var s:r.safety()){String key=s.context().name().toLowerCase(Locale.ROOT);x.put(key+"SourceReportedFlipCount",CompositionDecisionTimeProvenanceCapture.s(s.sourceReported()));x.put(key+"FalsePositiveCount",CompositionDecisionTimeProvenanceCapture.s(s.falsePositive()));x.put(key+"FalseNegativeCount",CompositionDecisionTimeProvenanceCapture.s(s.falseNegative()));x.put(key+"Corrected4C7NearMidFar",s.near()+"/"+s.mid()+"/"+s.far());x.put(key+"CorrectedHistoricalSafetyResult",s.safe()?"PASS":"FAIL");}
        List<CompositionWinnerDecisionProvenance>base=r.actual().stream().filter(p->p.context()==TeamCompositionContext.BASE_DEFENSE).toList();x.put("baseAttackerFlipCount",s(base.stream().filter(p->p.runtimeWinner()==p.attackingSide()).count()));x.put("baseDefenderFlipCount",s(base.stream().filter(p->p.runtimeWinner()==p.defendingSide()).count()));x.put("baseAttackerEconomicAdvantageOffsetCount",s(base.stream().filter(p->relation(p.blueGold()-p.redGold(),p.compositionEdge()).equals("OPPOSING_DIRECTION")&&p.runtimeWinner()==p.attackingSide()).count()));x.put("baseDefenderEconomicAdvantageOffsetCount",s(base.stream().filter(p->relation(p.blueGold()-p.redGold(),p.compositionEdge()).equals("OPPOSING_DIRECTION")&&p.runtimeWinner()==p.defendingSide()).count()));x.put("baseRoleSignMismatchCount",s(base.stream().filter(p->(p.compositionEdge()>0?TeamSide.BLUE:TeamSide.RED)!=p.runtimeWinner()).count()));x.put("baseAttackerDefenderSnapshotMissingCount",s(base.stream().filter(p->p.attackingSide()==null||p.defendingSide()==null).count()));x.put("siegeContextSpecializationCount",s(r.actual().stream().filter(p->p.context()==TeamCompositionContext.SIEGE).count()));
        x.put("objectiveDetailedPropagationCount",s(r.replays().stream().filter(p->p.source().objectiveChanged()).count()));x.put("structureDetailedPropagationCount",s(r.replays().stream().filter(p->p.source().structureChanged()).count()));x.put("finalWinnerDetailedProvenanceCount",s(r.replays().stream().filter(p->p.source().offWinner()!=p.source().candidateWinner()).count()));
    }

    static List<Map<String,String>>read(Path p)throws IOException{List<String>lines=Files.readAllLines(p,StandardCharsets.UTF_8),h=CompositionAuditOnlySemanticsRuntime.csv(lines.getFirst());List<Map<String,String>>out=new ArrayList<>();for(String line:lines.subList(1,lines.size()))if(!line.isBlank()){List<String>v=CompositionAuditOnlySemanticsRuntime.csv(line);Map<String,String>r=new LinkedHashMap<>();for(int i=0;i<h.size();i++)r.put(h.get(i),v.get(i));out.add(r);}return out;}static List<List<String>>header(String...x){return new ArrayList<>(List.of(List.of(x)));}static List<List<String>>metrics(String...x){List<List<String>>r=header("metric","value");for(int i=0;i<x.length;i+=2)r.add(List.of(x[i],x[i+1]));return r;}static void csv(String name,List<List<String>>rows)throws IOException{StringBuilder out=new StringBuilder();for(List<String>row:rows){for(int i=0;i<row.size();i++){if(i>0)out.append(',');String v=row.get(i);if(v.contains(",")||v.contains("\"")||v.contains("\n"))out.append('"').append(v.replace("\"","\"\"")).append('"');else out.append(v);}out.append('\n');}Files.writeString(OUT.resolve(name),out,StandardCharsets.UTF_8);}static Map<Path,String>sourceHashes()throws IOException{Map<Path,String>x=new LinkedHashMap<>();for(Path p:List.of(H7.resolve("composition-key-specific-fresh-holdout-summary.csv"),H7.resolve("composition-key-specific-fresh-holdout-audit.log"),A71.resolve("composition-fresh-holdout-attribution-summary.csv"),A71.resolve("composition-fresh-holdout-attribution-audit.log")))x.put(p,sha256(p));return Map.copyOf(x);}static String sha256(Path p)throws IOException{return sha256(Files.readAllBytes(p));}static String sha256(String x){return sha256(x.getBytes(StandardCharsets.UTF_8));}static String sha256(byte[]x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x));}catch(Exception e){throw new IllegalStateException(e);}}

    record Bands(double p25,double p75){String band(double x){return x<=p25?"NEAR":x<=p75?"MID":"FAR";}}record ApplicationId(int caseIndex,int attemptId,TeamCompositionContext context){String stableId(){return caseIndex+"|"+attemptId+"|"+context;}boolean matches(CompositionWinnerDecisionProvenance p){return p.caseIndex()==caseIndex&&p.attemptId().sequence()==attemptId&&p.context()==context;}}record SourceApp(ApplicationId id,int time,double baselineGap,double edge,double gain,double modifier,double candidateGap,double candidateProbability,double sample,TeamSide winner,boolean actualFlip){}
    record SourceGame(int caseIndex,long seed,String blue,String red,TeamSide offWinner,TeamSide candidateWinner,int offDuration,int candidateDuration,boolean publicDivergence,boolean objectiveChanged,boolean structureChanged){boolean matches(CompositionAuditOnlySemanticsRuntime.PairedGame p){return seed==p.seed()&&offWinner==p.offWinner()&&candidateWinner==p.auditWinner()&&offDuration==p.offDuration()&&candidateDuration==p.auditDuration()&&publicDivergence==!p.offTimelineHash().equals(p.auditTimelineHash())&&objectiveChanged==!p.offObjectiveSignature().equals(p.auditObjectiveSignature())&&structureChanged==!p.offStructureSignature().equals(p.auditStructureSignature());}}
