    record Result(Selection selection,List<ReplayCase>replays,List<CompositionWinnerDecisionProvenance>provenance,List<CompositionWinnerDecisionProvenance>actual,List<CompositionWinnerDecisionProvenance>controls,Map<String,List<RuleContribution>>rules,Correction correction,List<CorrectedSafety>safety,int sourceMismatch,int randomMismatch,int deterministicMismatch,int mutation,int integrityErrors,String verdict,Map<Path,String>before,Map<Path,String>after){int actualCaptureMissing(){return (int)KEYS.stream().mapToLong(c->Math.abs(expected(c)-actual.stream().filter(x->x.context()==c).count())).sum();}}
